import { schema } from './host-preflight-schema';
import {
  cloneMountTopology, type MountTopologyEvidence, cloneStoragePropagation, type StoragePropagationEvidence,
} from './mount-topology';

export type HostPreflightScope = keyof typeof schema.scopes;
export type HostPreflightCheck = {
  [Scope in HostPreflightScope]: keyof typeof schema.scopes[Scope];
}[HostPreflightScope];
export type HostPreflightReason = keyof typeof schema.reasons;
export type CheckResult = 'not-attempted' | 'not-required' | 'attempted' | 'passed' | 'failed';
export interface HostPreflightProgress {
  schemaVersion: 1 | 2;
  scope: HostPreflightScope;
  /** Present together in v2 records; never derived from private error text. */
  phase?: HostPreflightPhase;
  profile?: HostPreflightProfile;
  checks: { id: HostPreflightCheck; result: CheckResult; reason: HostPreflightReason }[];
  mountTopology?: MountTopologyEvidence;
  storagePropagation?: StoragePropagationEvidence;
}

export type HostPreflightPhase = 'preflight' | 'execution' | 'cleanup' | 'persistence';
export type HostPreflightProfile = 'common' | 'primary' | 'script' | 'agent';
export type HostPreflightContext = Readonly<{ phase: HostPreflightPhase; profile: HostPreflightProfile }>;

// Keep classification out of error messages, which may contain private paths.
const reasons = new WeakMap<object, HostPreflightReason>();
export function markHostPreflightError<T>(error: T, reason: HostPreflightReason): T {
  if (error && typeof error === 'object') reasons.set(error, reason);
  return error;
}

export function hostPreflightReason(error: unknown): HostPreflightReason {
  if (!error || typeof error !== 'object') return 'unknown';
  const classified = reasons.get(error);
  if (classified) return classified;
  const code = 'code' in error ? error.code : undefined;
  return typeof code === 'string' && code !== 'none'
    && Object.prototype.hasOwnProperty.call(schema.reasons, code) ? code as HostPreflightReason : 'unknown';
}

export class HostPreflightCleanupError extends Error {
  readonly cause: unknown;
  readonly cleanupError: unknown;

  constructor(cause: unknown, cleanupError: unknown) {
    super('Host preflight failed and cleanup failed');
    this.cause = cause;
    this.cleanupError = cleanupError;
    markHostPreflightError(this, hostPreflightReason(cause));
  }
}

export class HostPreflightReportingError extends Error {
  readonly cause: unknown;
  readonly reportingError: unknown;

  constructor(cause: unknown, reportingError: unknown) {
    super('Host preflight failed and publishing its diagnostic failed');
    this.cause = cause;
    this.reportingError = reportingError;
    markHostPreflightError(this, hostPreflightReason(cause));
  }
}

/** Reports only executed gates; constructing a plan does not pass any check. */
export class HostPreflightReporter {
  private readonly progress: HostPreflightProgress;

  constructor(
    readonly scope: HostPreflightScope,
    private readonly publish?: (value: HostPreflightProgress) => void,
    private readonly onFailure?: (
      report: HostPreflightReporter,
      id: HostPreflightCheck,
      error: unknown,
    ) => void,
    private readonly context?: HostPreflightContext,
    checks?: HostPreflightProgress['checks'],
  ) {
    this.progress = {
      schemaVersion: context ? 2 : 1, scope,
      ...(context ? { phase: context.phase, profile: context.profile } : {}),
      checks: checks ?? (Object.keys(schema.scopes[scope]) as HostPreflightCheck[])
        .map((id) => ({ id, result: 'not-attempted', reason: 'none' })),
    };
    this.emit();
  }

  private emit(): void {
    this.publish?.({
      ...this.progress, checks: this.progress.checks.map((check) => ({ ...check })),
      ...(this.progress.mountTopology ? { mountTopology: cloneMountTopology(this.progress.mountTopology) } : {}),
      ...(this.progress.storagePropagation
        ? { storagePropagation: cloneStoragePropagation(this.progress.storagePropagation) } : {}),
    });
  }

  fork(scope: HostPreflightScope, context = this.context): HostPreflightReporter {
    // Profiles within one scope contribute to the same admission checklist.
    return new HostPreflightReporter(scope, this.publish, this.onFailure,
      context && { ...context, phase: scope.includes('cleanup') ? 'cleanup' : context.phase },
      scope === this.scope ? this.progress.checks : undefined);
  }

  topology(value: MountTopologyEvidence): void {
    this.progress.mountTopology = cloneMountTopology(value);
    this.emit();
  }

  propagation(value: StoragePropagationEvidence): void {
    this.progress.storagePropagation = cloneStoragePropagation(value);
    this.emit();
  }

  notRequired(id: HostPreflightCheck): void {
    const check = this.progress.checks.find((candidate) => candidate.id === id);
    if (!check) throw new Error('Unknown host preflight check');
    const checkId = `${this.progress.scope}/${check.id}`;
    if (!schema.optionalChecks.includes(checkId)) {
      throw new Error(`Required startup check "${checkId}" cannot be skipped`);
    }
    check.result = 'not-required';
    check.reason = 'none';
    this.emit();
  }

  attempt(id: HostPreflightCheck): void {
    const check = this.progress.checks.find((candidate) => candidate.id === id);
    if (!check) throw new Error('Unknown host preflight check');
    check.result = 'attempted';
    check.reason = 'none';
    this.emit();
  }

  fail(id: HostPreflightCheck, error: unknown): void {
    const check = this.progress.checks.find((candidate) => candidate.id === id);
    if (!check) throw new Error('Unknown host preflight check');
    check.result = 'failed';
    check.reason = hostPreflightReason(error);
    this.emit();
    this.onFailure?.(this, id, error);
  }

  private pass(id: HostPreflightCheck): void {
    const check = this.progress.checks.find((candidate) => candidate.id === id)!;
    check.result = 'passed';
    this.emit();
  }

  checkSync<T>(id: HostPreflightCheck, operation: () => T): T {
    this.attempt(id);
    try {
      const result = operation();
      this.pass(id);
      return result;
    } catch (error) {
      try {
        this.fail(id, error);
      } catch (reportingError) {
        throw new HostPreflightReportingError(error, reportingError);
      }
      throw error;
    }
  }

  async check<T>(id: HostPreflightCheck, operation: () => Promise<T> | T): Promise<T> {
    const check = this.progress.checks.find((candidate) => candidate.id === id);
    if (!check) throw new Error('Unknown host preflight check');
    this.attempt(id);
    try {
      const result = await operation();
      this.pass(id);
      return result;
    } catch (error) {
      try {
        this.fail(id, error);
      } catch (reportingError) {
        throw new HostPreflightReportingError(error, reportingError);
      }
      throw error;
    }
  }
}
